import{_ as n,c as a,o as t,a2 as s}from"./chunks/framework.PGES7OoM.js";const r="/assets/send-to-curvy-id.BThQNc-I.png",o="/assets/send-to-external-wallet.DFCgzF8x.png",i="/assets/send-as-a-link-warning.BLZ_xH64.png",l="/assets/send-as-a-link.DWvda9jE.png",m=JSON.parse('{"title":"Send assets privately","description":"","frontmatter":{"rawMarkdown":"# Send assets privately\\n\\nThere are three ways to send assets from your Curvy web app, depending on whether the recipient:\\n\\n- already has a registered Curvy ID: [Send to Curvy ID](#send-to-curvy-id)\\n- wants to receive funds to a regular Ethereum account (EOA address): [Send to external wallet](#send-to-external-wallet)\\n- doesn\'t have a crypto wallet or address but wants to onboard to Curvy: [Send as a link](#send-as-a-link)\\n\\n## Send to Curvy ID\\n\\nWhen the recipient already has a registered Curvy ID, you can select the *Send to Curvy ID* option.\\n\\nIn the screenshot below, you can see an example of sending to *mihailo.curvy.name*:\\n\\n![Send to Curvy ID](send-to-curvy-id.png)\\n\\n## Send to external wallet\\n\\nWhen the recipient only has a blockchain address they can share with you, you\'ll need to select\\nboth the network where they will receive the funds and the exact address.\\n\\nIn the example below, we are sending the funds to `0xd8d...` on the Polygon network.\\n\\n![Send to external wallet](send-to-external-wallet.png)\\n\\n## Send as a link\\n\\nThe third option in the send dialog, **Send as a link**, allows you to generate a single-use link that\\nanyone can use to register or log in to a Curvy account and claim the funds you\'ve sent them.\\n\\nThis is useful in situations where:\\n\\n- You have a secure messaging channel with the recipient but don\'t know their address or Curvy name\\n- The user doesn\'t have Curvy or any other crypto wallet\\n- You want to give someone a crypto \\"giftcard\\"\\n\\n> [!WARNING]\\n> A couple of important things about **Send as a link** feature:\\n> <br>\\n>\\n> 1. Curvy links don\'t expire! The only way for you to get back the funds that were unclaimed is to claim the funds using the link yourself.\\n> <br>\\n> 2. Make sure that you always back up the link before sending!\\n> <br>\\n> 3. Keep the links safe, as anyone who gains access to them will also gain access to the funds they are sending!\\n> <br>\\n\\nUpon entering the amount and currency, you will be presented with a warning similar to the one above:\\n\\n![Send as a link warning](send-as-a-link-warning.png)\\n\\nAfter confirming the action, you will need for the private transfer process to finish:\\n\\n![Send as a link ](send-as-a-link.png)\\n\\nAfter that, your recipient can simply open a link similar to the one below:\\n\\n```\\nhttps://app.curvy.box#737461&5&91227993...883431253847704268123135462&5000000000000000&1\\n```\\n\\nand any Curvy ID they log in to or register will automatically claim these funds upon opening the app, rendering the link no longer usable.\\n","rawMarkdownPath":"/_raw/for-users/send-assets-privately.md","rawMarkdownTitle":"Send assets privately","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-users/send-assets-privately.md"},"headers":[],"relativePath":"for-users/send-assets-privately.md","filePath":"for-users/send-assets-privately.md","lastUpdated":1773768298000}'),d={name:"for-users/send-assets-privately.md"};function h(u,e,p,c,y,g){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="send-assets-privately" tabindex="-1">Send assets privately <a class="header-anchor" href="#send-assets-privately" aria-label="Permalink to &quot;Send assets privately&quot;">​</a></h1><p>There are three ways to send assets from your Curvy web app, depending on whether the recipient:</p><ul><li>already has a registered Curvy ID: <a href="#send-to-curvy-id">Send to Curvy ID</a></li><li>wants to receive funds to a regular Ethereum account (EOA address): <a href="#send-to-external-wallet">Send to external wallet</a></li><li>doesn&#39;t have a crypto wallet or address but wants to onboard to Curvy: <a href="#send-as-a-link">Send as a link</a></li></ul><h2 id="send-to-curvy-id" tabindex="-1">Send to Curvy ID <a class="header-anchor" href="#send-to-curvy-id" aria-label="Permalink to &quot;Send to Curvy ID&quot;">​</a></h2><p>When the recipient already has a registered Curvy ID, you can select the <em>Send to Curvy ID</em> option.</p><p>In the screenshot below, you can see an example of sending to <em>mihailo.curvy.name</em>:</p><p><img src="'+r+'" alt="Send to Curvy ID"></p><h2 id="send-to-external-wallet" tabindex="-1">Send to external wallet <a class="header-anchor" href="#send-to-external-wallet" aria-label="Permalink to &quot;Send to external wallet&quot;">​</a></h2><p>When the recipient only has a blockchain address they can share with you, you&#39;ll need to select both the network where they will receive the funds and the exact address.</p><p>In the example below, we are sending the funds to <code>0xd8d...</code> on the Polygon network.</p><p><img src="'+o+'" alt="Send to external wallet"></p><h2 id="send-as-a-link" tabindex="-1">Send as a link <a class="header-anchor" href="#send-as-a-link" aria-label="Permalink to &quot;Send as a link&quot;">​</a></h2><p>The third option in the send dialog, <strong>Send as a link</strong>, allows you to generate a single-use link that anyone can use to register or log in to a Curvy account and claim the funds you&#39;ve sent them.</p><p>This is useful in situations where:</p><ul><li>You have a secure messaging channel with the recipient but don&#39;t know their address or Curvy name</li><li>The user doesn&#39;t have Curvy or any other crypto wallet</li><li>You want to give someone a crypto &quot;giftcard&quot;</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>A couple of important things about <strong>Send as a link</strong> feature: <br></p><ol><li>Curvy links don&#39;t expire! The only way for you to get back the funds that were unclaimed is to claim the funds using the link yourself. <br></li><li>Make sure that you always back up the link before sending! <br></li><li>Keep the links safe, as anyone who gains access to them will also gain access to the funds they are sending! <br></li></ol></div><p>Upon entering the amount and currency, you will be presented with a warning similar to the one above:</p><p><img src="'+i+'" alt="Send as a link warning"></p><p>After confirming the action, you will need for the private transfer process to finish:</p><p><img src="'+l+'" alt="Send as a link "></p><p>After that, your recipient can simply open a link similar to the one below:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://app.curvy.box#737461&amp;5&amp;91227993...883431253847704268123135462&amp;5000000000000000&amp;1</span></span></code></pre></div><p>and any Curvy ID they log in to or register will automatically claim these funds upon opening the app, rendering the link no longer usable.</p>',23)])])}const v=n(d,[["render",h]]);export{m as __pageData,v as default};
